/* Search Bar Styling */
.search-container {
    position: relative;
    margin-bottom: 25px;
}

.search-icon {
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    color: #4a7c92;
    font-size: 18px;
}

.search-container input {
    width: 100%;
    padding: 12px 12px 12px 45px;
    border: 1.5px solid #4a74d4; /* Blue border */
    border-radius: 6px;
    font-size: 16px;
    color: #555;
    outline: none;
}

/* Links Wrapper */
.links-wrapper {
    display: flex;
    flex-direction: column;
    gap: 12px; /* Spacing between cards */
}

/* Individual Link Card */
.link-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 15px;
    transition: box-shadow 0.3s ease;
}

.link-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.link-text {
    font-size: 16px;
    color: #333;
    font-weight: 500;
}

/* Visit Website Button */
.visit-btn {
    background-color: #dbe4ff; /* Very light blue background */
    color: #2c54c1; /* Strong blue text */
    text-decoration: none;
    font-size: 12px;
    font-weight: bold;
    padding: 10px 20px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background 0.3s ease;
}

.visit-btn:hover {
    background-color: #c9d6ff;
}

.visit-btn i {
    font-size: 14px;
}

/* Responsive adjustment */
@media (max-width: 600px) {
    .link-card {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }
    .visit-btn {
        width: 100%;
        justify-content: center;
    }
}

/* Container */
.container {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px;
  font-family: "Noto Sans", sans-serif;
}

/* Search box - Fixed 16px */
.search-box {
  width: 260px;
  border: 1px solid #7aa0ff;
  padding: 8px 12px;
  font-size: 16px;
  outline: none;
}

/* Heading 1: Desktop 36px / Mobile 24px */
h1 {
  font-size: 36px;
  font-weight: 700;
  color: #111;
  margin: 20px 0 12px;
}

/* Heading 2: Desktop 24px / Mobile 20px */
h2 {
  font-size: 24px;
  font-weight: 600;
  color: #2b5dab;
  margin: 28px 0 12px;
}

/* Heading 3 / Subtitle: Desktop 20px / Mobile 16px */
h3 {
  font-size: 20px;
  font-weight: 600;
  color: #111;
  margin: 24px 0 10px;
}

/* Paragraphs & Text Content - Fixed 16px */
p, .text {
  font-size: 16px;
  font-weight: 400;
  line-height: 1.8;
  margin-bottom: 14px;
  color: #222;
}

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 20px 0;
}

th, td {
  border: 1px solid #d1d5db;
  padding: 10px 14px;
  text-align: left;
  line-height: 1.6;
}

/* Table Headers - Fixed 16px Bold */
th {
  background: #f2f2f2;
  font-size: 16px;
  font-weight: 700;
  color: #111;
  vertical-align: middle;
}

/* Table Cells - Fixed 16px Regular */
td {
  font-size: 16px;
  font-weight: 400;
  color: #222;
  vertical-align: top;
}

/* Links - Fixed 16px */
a {
  color: #1a5fd0;
  text-decoration: none;
  font-size: 16px;
}

a:hover {
  text-decoration: underline;
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
  .search-box {
    width: 100%;
    font-size: 16px;
  }

  h1 {
    font-size: 24px;
  }

  h2 {
    font-size: 20px;
  }

  h3, p, .text, th, td, a {
    font-size: 16px; /* Mobile par bhi minimum 16px hi rahega */
  }
}

